35	func newAttachCmd() *cobra.Command {
36		var (
37			force     bool
38			agentFlag string
39		)
40		cmd := &cobra.Command{
41			Use:   "attach <session-id>",
42			Short: "Attach an existing agent session",
43			Long: `Attach an existing agent session that wasn't captured by hooks.
44	
45	This creates a checkpoint from the session's transcript and links it to the
46	last commit. Use this when hooks failed to fire or weren't installed when
47	the session started, or to attach a research session.
48	
49	If the last commit already has a checkpoint, the session is added to it.
50	Otherwise a new checkpoint is created.
51	
52	Supported agents: claude-code, gemini, opencode, codex, cursor, copilot-cli, factoryai-droid`,
53			RunE: func(cmd *cobra.Command, args []string) error {
54				if len(args) != 1 {
55					return cmd.Help()
56				}
57				if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
58					return nil
59				}
60				agentName := types.AgentName(agentFlag)
61				return runAttach(cmd.Context(), cmd.OutOrStdout(), args[0], agentName, force)
62			},
63		}
64		cmd.Flags().BoolVarP(&force, "force", "f", false, "Skip confirmation and amend the last commit with the checkpoint trailer")
65		cmd.Flags().StringVarP(&agentFlag, "agent", "a", string(agent.DefaultAgentName), "Agent that created the session (claude-code, gemini, opencode, codex, cursor, copilot-cli, factoryai-droid)")
66		return cmd
67	}
