455	// --- Helpers ---
456	
457	// limitedWriter wraps a bytes.Buffer and stops writing after limit bytes,
458	// preventing unbounded memory growth from external process output.
459	type limitedWriter struct {
460		buf       *bytes.Buffer
461		limit     int
462		truncated bool
463	}
464	
465	func (w *limitedWriter) Write(p []byte) (int, error) {
466		remaining := w.limit - w.buf.Len()
467		if remaining <= 0 {
468			w.truncated = true
469			return len(p), nil // discard, but report success so the process isn't killed
470		}
471		if len(p) > remaining {
472			p = p[:remaining]
473			w.truncated = true
474		}
475		n, err := w.buf.Write(p)
476		if err != nil {
477			return n, fmt.Errorf("writing to limited buffer: %w", err)
478		}
479		return n, nil
480	}
