92	// Subagent transcripts are stored as agent-{agentId}.jsonl in the same directory
93	// as the main transcript.
94	func AgentTranscriptPath(transcriptDir, agentID string) string {
95		return filepath.Join(transcriptDir, fmt.Sprintf("agent-%s.jsonl", agentID))
