98	// toolResultBlock represents a tool_result in a user message
99	type toolResultBlock struct {
100		Type      string `json:"type"`
101		ToolUseID string `json:"tool_use_id"`
102	}
103	
104	// userMessageWithToolResults represents a user message that may contain tool results
105	type userMessageWithToolResults struct {
106		Content []toolResultBlock `json:"content"`
107	}
108	
109	// FindCheckpointUUID finds the UUID of the message containing the tool_result
110	// for the given tool_use_id. This is used to find the checkpoint point for
111	// transcript truncation when rewinding to a task.
112	// Returns the UUID and true if found, empty string and false otherwise.
113	func FindCheckpointUUID(lines []transcriptLine, toolUseID string) (string, bool) {
114		for _, line := range lines {
115			if line.Type != transcript.TypeUser {
116				continue
117			}
118	
119			var msg userMessageWithToolResults
120			if err := json.Unmarshal(line.Message, &msg); err != nil {
121				continue
122			}
123	
124			for _, block := range msg.Content {
125				if block.Type == "tool_result" && block.ToolUseID == toolUseID {
126					return line.UUID, true
127				}
128			}
129		}
130		return "", false
131	}
132	
133	// TruncateTranscriptAtUUID returns transcript lines up to and including the
134	// line with the given UUID. If the UUID is not found or is empty, returns
135	// the entire transcript.
136	//
137	//nolint:revive // Exported for testing purposes
138	func TruncateTranscriptAtUUID(lines []transcriptLine, uuid string) []transcriptLine {
139		if uuid == "" {
140			return lines
141		}
142	
143		for i, line := range lines {
144			if line.UUID == uuid {
145				return lines[:i+1]
146			}
147		}
148	
149		// UUID not found, return full transcript
150		return lines
151	}
