153	// writeTranscript writes transcript lines to a file in JSONL format.
154	func writeTranscript(path string, lines []transcriptLine) error {
155		file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
156		if err != nil {
157			return fmt.Errorf("failed to create file: %w", err)
158		}
159		defer func() { _ = file.Close() }()
160	
161		for _, line := range lines {
162			data, err := json.Marshal(line)
163			if err != nil {
164				return fmt.Errorf("failed to marshal line: %w", err)
165			}
166			if _, err := file.Write(data); err != nil {
167				return fmt.Errorf("failed to write line: %w", err)
168			}
169			if _, err := file.WriteString("\n"); err != nil {
170				return fmt.Errorf("failed to write newline: %w", err)
171			}
172		}
173	
174		return nil
175	}
