177	// TranscriptPosition contains the position information for a transcript file.
178	type TranscriptPosition struct {
179		LastUUID  string // Last non-empty UUID (from user/assistant messages)
180		LineCount int    // Total number of lines
181	}
182	
183	// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
184	// Returns empty position if file doesn't exist or is empty.
185	// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
186	func GetTranscriptPosition(path string) (TranscriptPosition, error) {
187		if path == "" {
188			return TranscriptPosition{}, nil
189		}
190	
191		file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
192		if err != nil {
193			if os.IsNotExist(err) {
194				return TranscriptPosition{}, nil
195			}
196			return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
197		}
198		defer func() { _ = file.Close() }()
199	
200		var pos TranscriptPosition
201		reader := bufio.NewReader(file)
202	
203		for {
204			lineBytes, err := reader.ReadBytes('\n')
205			if err != nil && err != io.EOF {
206				return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
207			}
208	
209			if len(lineBytes) == 0 {
210				if err == io.EOF {
211					break
212				}
213				continue
214			}
215	
216			pos.LineCount++
217	
218			// Parse line to extract UUID (only from user/assistant messages, not summaries)
219			var line transcriptLine
220			if err := json.Unmarshal(lineBytes, &line); err == nil {
221				if line.UUID != "" {
222					pos.LastUUID = line.UUID
223				}
224			}
225	
226			if err == io.EOF {
227				break
228			}
229		}
230	
231		return pos, nil
232	}
