12	// Wrap returns the Agent wrapped as an agent.Agent that implements ALL optional
13	// interfaces (forwarding to the underlying external agent) plus CapabilityDeclarer.
14	// The As* helpers in the agent package use DeclaredCapabilities() to gate access,
15	// so callers only see capabilities the external binary actually declared.
16	func Wrap(ea *Agent) (agent.Agent, error) {
17		if ea == nil {
18			return nil, errors.New("unable to wrap nil agent")
19		}
20		base := &wrappedAgent{
21			ea:   ea,
22			caps: ea.info.Capabilities,
23		}
24		if len(ea.info.ProtectedFiles) > 0 {
25			return &wrappedAgentWithProtectedFiles{wrappedAgent: base}, nil
26		}
27		return base, nil
28	}
