94	// resolveActiveBranch parses JSONL data and returns the set of entry IDs on
95	// the active conversation branch. Pi transcripts form a tree (entries have id
96	// and parentId); the active branch is the path from the root to the last
97	// message entry in the file.
98	// Returns nil if the transcript has no tree structure or cannot be resolved.
99	func resolveActiveBranch(data []byte) map[string]bool {
100		type node struct {
101			Type     string  `json:"type"`
102			ID       string  `json:"id"`
103			ParentID *string `json:"parentId"`
104		}
105	
106		var lastMessageID string
107		hasTree := false
108		parentOf := make(map[string]string)
109	
110		scanner := newJSONLScanner(data)
111		for scanner.Scan() {
112			var n node
113			if err := json.Unmarshal(scanner.Bytes(), &n); err != nil || n.ID == "" {
114				continue
115			}
116			if n.ParentID != nil {
117				parentOf[n.ID] = *n.ParentID
118				if *n.ParentID != "" {
119					hasTree = true
120				}
121			}
122			if n.Type == entryTypeMessage {
123				lastMessageID = n.ID
124			}
125		}
126	
127		// No tree references — all entries are on the active branch.
128		if !hasTree || lastMessageID == "" {
129			return nil
130		}
131	
132		active := make(map[string]bool)
133		for cur := lastMessageID; cur != ""; {
134			if active[cur] {
135				break // cycle protection
136			}
137			active[cur] = true
138			parent, ok := parentOf[cur]
139			if !ok {
140				break
141			}
142			cur = parent
143		}
144	
145		return active
146	}
