207	func (a *Agent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
208		if maxSize <= 0 {
209			return nil, fmt.Errorf("max-size must be positive, got %d", maxSize)
210		}
211		var chunks [][]byte
212		for len(content) > 0 {
213			end := maxSize
214			if end > len(content) {
215				end = len(content)
216			}
217			chunks = append(chunks, content[:end])
218			content = content[end:]
219		}
220		return chunks, nil
221	}
222	
223	func (a *Agent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
224		var data []byte
225		for _, chunk := range chunks {
226			data = append(data, chunk...)
227		}
228		return data, nil
229	}
