232	// The CLI uses this value as the offset for ExtractModifiedFiles, so units
233	// must match: both use line count (consistent with Claude Code).
234	func (a *Agent) GetTranscriptPosition(path string) (int, error) {
235		data, err := os.ReadFile(path) //nolint:gosec // path from session state
236		if err != nil {
237			if os.IsNotExist(err) {
238				return 0, nil
239			}
240			return 0, err
241		}
242		return countLines(data), nil
243	}
