245	func (a *Agent) ExtractModifiedFiles(path string, offset int) ([]string, int, error) {
246		data, err := os.ReadFile(path)
247		if err != nil {
248			return nil, 0, err
249		}
250	
251		totalLines := countLines(data)
252		active := resolveActiveBranch(data)
253	
254		content := skipLines(data, offset)
255	
256		seen := make(map[string]bool)
257		var files []string
258	
259		scanner := newJSONLScanner(content)
260		for scanner.Scan() {
261			var entry messageEntry
262			if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
263				continue
264			}
265			if entry.Type != entryTypeMessage {
266				continue
267			}
268			if active != nil && !active[entry.ID] {
269				continue
270			}
271			if entry.Message.Role != "assistant" {
272				continue
273			}
274	
275			var items []contentItem
276			if err := json.Unmarshal(entry.Message.Content, &items); err != nil {
277				continue
278			}
279	
280			for _, item := range items {
281				if item.Type != "toolCall" {
282					continue
283				}
284				if item.Name != "write" && item.Name != "edit" {
285					continue
286				}
287				var args struct {
288					Path string `json:"path"`
289				}
290				if err := json.Unmarshal(item.Arguments, &args); err != nil {
291					continue
292				}
293				if args.Path != "" && !seen[args.Path] {
294					seen[args.Path] = true
295					files = append(files, args.Path)
296				}
297			}
298		}
299	
300		return files, totalLines, nil
301	}
