310	
311		content := skipLines(data, offset)
312	
313		var prompts []string
314		scanner := newJSONLScanner(content)
315		for scanner.Scan() {
316			var entry messageEntry
317			if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
318				continue
319			}
320			if entry.Type != entryTypeMessage || entry.Message.Role != "user" {
321				continue
322			}
323			if active != nil && !active[entry.ID] {
324				continue
325			}
326	
327			var items []contentItem
328			if err := json.Unmarshal(entry.Message.Content, &items); err != nil {
329				continue
330			}
331	
332			for _, item := range items {
333				if item.Type == "text" && item.Text != "" {
334					prompts = append(prompts, item.Text)
