382	func (a *Agent) CalculateTokens(data []byte, offset int) (protocol.TokenUsageResponse, error) {
383		active := resolveActiveBranch(data)
384	
385		content := skipLines(data, offset)
386	
387		var result protocol.TokenUsageResponse
388		scanner := newJSONLScanner(content)
389		for scanner.Scan() {
390			var entry messageEntry
391			if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
392				continue
393			}
394			if entry.Type != entryTypeMessage || entry.Message.Role != "assistant" || entry.Message.Usage == nil {
395				continue
396			}
397			if active != nil && !active[entry.ID] {
398				continue
399			}
400	
401			result.InputTokens += entry.Message.Usage.Input
402			result.OutputTokens += entry.Message.Usage.Output
403			result.CacheReadTokens += entry.Message.Usage.CacheRead
404			result.CacheCreationTokens += entry.Message.Usage.CacheWrite
405			result.APICallCount++
406		}
407	
408		return result, nil
409	}
