11	)
12	
13	const (
14		extensionDir      = ".pi/extensions/entire"
15		extensionFile     = ".pi/extensions/entire/index.ts"
16		activeSessionFile = "pi-active-session"
17	)
18	
19	// piHookPayload is the JSON the TypeScript extension sends to
20	// `entire agent hook pi <event>`, which arrives on stdin of parse-hook.
21	type piHookPayload struct {
22		Type         string `json:"type"`
23		Cwd          string `json:"cwd,omitempty"`
24		SessionFile  string `json:"session_file,omitempty"`
25		SessionID    string `json:"session_id,omitempty"`
26		Prompt       string `json:"prompt,omitempty"`
27		MessageCount int    `json:"message_count,omitempty"`
28		TurnIndex    int    `json:"turn_index,omitempty"`
29	}
30	
31	func (a *Agent) ParseHook(hookName string, input []byte) (*protocol.EventJSON, error) {
32		if len(input) == 0 {
33			return nil, nil
34		}
35	
36		var payload piHookPayload
37		if err := json.Unmarshal(input, &payload); err != nil {
38			return nil, fmt.Errorf("parse hook payload: %w", err)
39		}
40	
41		sessionID := payload.SessionID
42		if sessionID == "" {
43			sessionID = extractSessionIDFromPath(payload.SessionFile)
44		}
45	
46		now := time.Now().UTC().Format(time.RFC3339)
47	
48		switch hookName {
49		case "session_start":
50			cacheSessionID(sessionID)
51			return &protocol.EventJSON{
52				Type:      1, // SessionStart
53				SessionID: sessionID,
54				Timestamp: now,
55			}, nil
56	
57		case "before_agent_start":
58			if sessionID == "" {
59				sessionID = readCachedSessionID()
60			} else {
61				cacheSessionID(sessionID)
62			}
63			// Provide the live pi session file as SessionRef so that
64			// state.TranscriptPath is populated before any mid-turn commits.
65			// Without this, the post-commit hook cannot condense when no
66			// shadow branch exists yet (no prior step checkpoints).
67			return &protocol.EventJSON{
68				Type:       2, // TurnStart
69				SessionID:  sessionID,
70				SessionRef: payload.SessionFile,
71				Prompt:     payload.Prompt,
72				Timestamp:  now,
73			}, nil
74	
75		case "agent_end":
76			if sessionID == "" {
77				sessionID = readCachedSessionID()
78			}
79			sessionRef := captureTranscript(sessionID, payload.SessionFile)
80			return &protocol.EventJSON{
81				Type:       3, // TurnEnd
82				SessionID:  sessionID,
83				SessionRef: sessionRef,
84				Timestamp:  now,
85			}, nil
86	
87		case "session_shutdown":
88			clearCachedSessionID()
89			return nil, nil
90	
91		default:
92			return nil, nil
93		}
94	}
95	
96	func (a *Agent) InstallHooks(_ bool, force bool) (int, error) {
97		root := protocol.RepoRoot()
98	
99		// If already installed and not forcing, return 0 (idempotent no-op).
100		if !force && a.AreHooksInstalled() {
101			return 0, nil
102		}
103	
104		dir := filepath.Join(root, extensionDir)
105		if err := os.MkdirAll(dir, 0o750); err != nil {
106			return 0, fmt.Errorf("create extension dir: %w", err)
107		}
108	
109		ext := generateExtension()
110	
111		path := filepath.Join(root, extensionFile)
112		if err := os.WriteFile(path, []byte(ext), 0o600); err != nil {
113			return 0, fmt.Errorf("write extension: %w", err)
114		}
115	
116		return 4, nil // 4 hooks: session_start, before_agent_start, agent_end, session_shutdown
117	}
