132	func generateExtension() string {
133		return `import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
134	import { execFile } from "node:child_process";
135	
136	export default function (pi: ExtensionAPI) {
137	  function fireHook(hookName: string, data: Record<string, unknown>): Promise<void> {
