541	func convertIDETranscript(ide *kiroIDETranscript) *kiroTranscript {
542		transcript := &kiroTranscript{}
543	
544		var pendingUser *kiroIDEHistoryEntry
545		for i := range ide.History {
546			entry := &ide.History[i]
547			switch entry.Message.Role {
548			case "user":
549				if pendingUser != nil {
550					transcript.History = append(transcript.History, ideEntryToPaired(pendingUser, nil))
551				}
552				pendingUser = entry
553			case "assistant":
554				transcript.History = append(transcript.History, ideEntryToPaired(pendingUser, entry))
555				pendingUser = nil
556			}
557		}
558	
559		if pendingUser != nil {
560			transcript.History = append(transcript.History, ideEntryToPaired(pendingUser, nil))
561		}
562	
563		return transcript
564	}
