566	func ideEntryToPaired(user, assistant *kiroIDEHistoryEntry) kiroHistoryEntry {
567		entry := kiroHistoryEntry{}
568	
569		if user != nil {
570			prompt := extractIDEText(user.Message.Content, true)
571			if prompt != "" {
572				content, err := json.Marshal(kiroPromptContent{
573					Prompt: struct {
574						Prompt string `json:"prompt"`
575					}{Prompt: prompt},
576				})
577				if err == nil {
578					entry.User.Content = content
579				}
580			} else {
581				entry.User.Content = user.Message.Content
582			}
583		}
584	
585		if assistant != nil {
586			text := extractIDEText(assistant.Message.Content, false)
587			if text != "" {
588				content, err := json.Marshal(kiroResponseContent{
589					Response: kiroResponsePayload{Content: text},
590				})
591				if err == nil {
592					entry.Assistant = content
593				}
594			} else {
595				entry.Assistant = assistant.Message.Content
596			}
597		}
598	
599		return entry
600	}
601	
602	// extractIDEText extracts text from a json.RawMessage that may be either a
603	// plain string or an array of content blocks. When blocksFirst is true, it
604	// tries to parse as blocks before falling back to a plain string (user
605	// messages); otherwise it tries plain string first (assistant messages).
606	func extractIDEText(content json.RawMessage, blocksFirst bool) string {
607		if len(content) == 0 {
608			return ""
609		}
610	
611		tryBlocks := func() string {
612			var blocks []kiroIDEContentBlock
613			if err := json.Unmarshal(content, &blocks); err == nil && len(blocks) > 0 {
614				for _, block := range blocks {
615					if block.Type == "text" && block.Text != "" {
616						return block.Text
617					}
618				}
619			}
620			return ""
621		}
622	
623		tryString := func() string {
624			var text string
625			if err := json.Unmarshal(content, &text); err == nil {
626				return text
627			}
628			return ""
629		}

